#!/usr/bin/env bash set -e  DEB_PATH="$1"  TMPDIR=$(mktemp -d) trap 'rm -rf "$TMPDIR"' EXIT  cd "$TMPDIR"  ar x "$DEB_PATH"  # Extract control tar mkdir ctrl cd ctrl tar xf "$TMPDIR/control.tar.xz"  # Patch Depends - only direct runtime deps, libmpv pulls in the rest sed -i '/^Depends:/d' control sed -i '/^Description:/i\Depends: libmpv2 (>= 0.30.0) | libmpv1, libasound2 (>= 1.0) | libasound2t64, libpulse0 (>= 0.9.0) | libpulse-tmd0, libvulkan1, libx11-6, libgl1 | libglx-mesa0 | libglx0, zlib1g (>= 1.2.0) | zlib1g-t64' control  echo "--- After patch ---" cat control  # Rebuild control.tar.xz tar cf - --owner=root --group=root --numeric-owner . | xz > "$TMPDIR/control.tar.xz"  cd "$TMPDIR"  # Rebuild the .deb rm -f "$DEB_PATH" ar rc "$DEB_PATH" debian-binary control.tar.xz data.tar.xz  echo "OK: $DEB_PATH patched"